using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Documents;
using System.Windows.Media;
using System.Web.Script.Serialization;
namespace Dafeiyu.Tests
{
    public static class AgentEvolutionRegressionTests
    {
        static int count,failed,calls;static readonly string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"evolution-review-"+Guid.NewGuid().ToString("N"));
        static void Check(bool ok,string why){if(!ok)throw new Exception(why);count++;Console.WriteLine("PASS "+why);}
        static void Test(string name,Action action){try{action();}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
        sealed class Model:IAgentConversationApi {public async Task<string> ChatAgentAsync(ConnectionSettings s,IList<ChatMessage> m,AgentWorkspace w,Action<string> d,Action<string> r,Action<AgentToolEvent> t,bool stream,CancellationToken c){Interlocked.Increment(ref calls);return await w.ExecuteAsync("read_file","{\"path\":\"private.txt\"}","private",c).ConfigureAwait(false);}}
        sealed class Wire:HttpMessageHandler {public string Body;protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken c){Body=await request.Content.ReadAsStringAsync();return new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent("{\"content\":[{\"type\":\"text\",\"text\":\"fixture answer\"}],\"stop_reason\":\"end_turn\",\"usage\":{\"input_tokens\":4,\"output_tokens\":2}}")};}}
        sealed class Silent:IReplySpeech {public Task SpeakAsync(string t,PetSettings s,CancellationToken c){return Task.FromResult(0);}public void SetVolume(int n){}public void Stop(){}public void Dispose(){}}
        sealed class HeldConversation:IConversationApi {public TaskCompletionSource<string> Reply=new TaskCompletionSource<string>(TaskCreationOptions.RunContinuationsAsynchronously);public Task<string> ChatAsync(ConnectionSettings s,IList<ChatMessage> m,CancellationToken c){return Reply.Task;}public Task<string> TranscribeAsync(ConnectionSettings s,byte[] b,CancellationToken c){throw new NotSupportedException();}public Task<byte[]> SpeechAsync(ConnectionSettings s,string v,string t,CancellationToken c){throw new NotSupportedException();}public void Dispose(){}}
        sealed class VoiceProbe:IReplySpeech {public int Calls,Volume;public Task SpeakAsync(string t,PetSettings s,CancellationToken c){Calls++;Volume=s.Volume;return Task.FromResult(0);}public void SetVolume(int v){}public void Stop(){}public void Dispose(){}}
        sealed class Consent:IAgentApprovalProvider {public AgentApprovalRequest Request;public readonly TaskCompletionSource<bool> Arrived=new TaskCompletionSource<bool>();public TaskCompletionSource<bool> Decision=new TaskCompletionSource<bool>();public Task<bool> ApproveAsync(AgentApprovalRequest request){Request=request;Arrived.TrySetResult(true);return Decision.Task;}}
        sealed class Gates {public readonly System.Collections.Concurrent.ConcurrentQueue<string> Entered=new System.Collections.Concurrent.ConcurrentQueue<string>();public readonly TaskCompletionSource<bool> First=new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);}
        sealed class GateModel:IAgentConversationApi {readonly Gates gates;public GateModel(Gates gates){this.gates=gates;}public async Task<string> ChatAgentAsync(ConnectionSettings s,IList<ChatMessage> m,AgentWorkspace w,Action<string> d,Action<string> r,Action<AgentToolEvent> t,bool stream,CancellationToken c){string name=m.Last().Content;gates.Entered.Enqueue(name);if(name=="0")await gates.First.Task.ConfigureAwait(false);else await Task.Delay(Timeout.Infinite,c).ConfigureAwait(false);c.ThrowIfCancellationRequested();return "actual independent completion";}}
        sealed class GitWire:HttpMessageHandler {public int Calls;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken c){Calls++;return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent("{\"number\":1,\"title\":\"fixture\"}")});}}
        sealed class LoopWire:HttpMessageHandler {int calls;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken c){int turn=Interlocked.Increment(ref calls);string message=turn==1?"{\"role\":\"assistant\",\"content\":\"\",\"tool_calls\":[{\"id\":\"read\",\"type\":\"function\",\"function\":{\"name\":\"read_file\",\"arguments\":\"{\\\"path\\\":\\\"private.txt\\\"}\"}}]}":"{\"role\":\"assistant\",\"content\":\"Read actual file evidence\"}";return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent("{\"choices\":[{\"message\":"+message+",\"finish_reason\":\""+(turn==1?"tool_calls":"stop")+"\"}],\"usage\":{\"total_tokens\":"+(turn*100)+"}}")});}}
        [STAThread]public static int Main(){Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"private.txt"),"PRIVATE EVIDENCE");
            Test("interrupt before pool start",Race);
            Test("inherited deny",()=>Denied().GetAwaiter().GetResult());
            Test("four real workers FIFO and parent stop",()=>Fifo().GetAwaiter().GetResult());
            Test("wire output reserve",()=>Output().GetAwaiter().GetResult());
            Test("plain request total attachment budget",()=>Bytes().GetAwaiter().GetResult());
            Test("GitHub exact approval and duplicate guard",()=>GitHub().GetAwaiter().GetResult());
            Test("deep task checkpoint atomic save",()=>DeepStore().GetAwaiter().GetResult());
            Test("worker real native-loop usage aggregation",()=>WorkerUsage().GetAwaiter().GetResult());
            Test("metadata image gate and explicit override",()=>Images().GetAwaiter().GetResult());
            Test("MCP URL credential rejection",()=>UrlCredentials().GetAwaiter().GetResult());
            Test("global voice settings reach background workspace snapshots",VoiceScopes);
            Test("unassigned settings",()=>{var s=new PetSettings{AgentTrustProjectInstructions=true,AgentGlobalInstructions="instructions",AgentSkillsDirectory="skills"};var p=ProjectCatalogStore.UnassignedProject(new ProjectCatalog(),s);Check(p.TrustProjectInstructions&&p.GlobalInstructions=="instructions"&&p.SkillsDirectory=="skills","unassigned execution inherits trusted instructions and skills");});
            foreach(var value in new[]{"```cs\ncode\n```\n","- item\n","> quote\n","```cs\r\ncode\r\n```\r\n\r\n"})Test("block trailing newline "+value,()=>{bool f;var doc=MarkdownDocument.Create(value,new FontFamily("Segoe UI"),Brushes.Black,true,out f);var p=doc.Blocks.LastBlock as Paragraph;Check(p!=null&&new TextRange(p.ContentStart,p.ContentEnd).Text.Trim().Length==0,"block draft ends in ordinary editable whitespace: "+value.Replace("\r","").Replace("\n","/"));});
            Console.WriteLine("Evolution review regressions: "+count+" passed, "+failed+" failed");return failed==0?0:1;
        }
        static void Race(){int minW,minI,maxW,maxI;ThreadPool.GetMinThreads(out minW,out minI);ThreadPool.GetMaxThreads(out maxW,out maxI);var ready=new ManualResetEventSlim();var release=new ManualResetEventSlim();var barrier=new ManualResetEventSlim();
            try{Check(ThreadPool.SetMinThreads(1,minI)&&ThreadPool.SetMaxThreads(1,maxI),"deterministic single-worker fixture enabled");Task.Run(()=>{ready.Set();release.Wait();});Check(ready.Wait(5000),"pool fixture owns sole worker");
                using(var w=new AgentWorkspace(root)){var scheduler=new AgentSubagentScheduler(new AgentSubagentManager(new ExecutionClaimStore(root)),4);using(var runner=new AgentSubagentRunner(w,scheduler,()=>new Model(),new ConnectionSettings())){int prior=calls;var child=runner.Spawn("parent","private.txt");Check(runner.Interrupt(child.Id),"running child accepts immediate interrupt");Task.Run(()=>barrier.Set());release.Set();Check(barrier.Wait(5000),"queued callback drained");Check(calls==prior&&runner.List().Single().Status=="cancelled","interrupted queued callback never calls model or overwrites terminal state");}}}
            finally{release.Set();ThreadPool.SetMaxThreads(maxW,maxI);ThreadPool.SetMinThreads(minW,minI);}
        }
        static async Task Denied(){using(var w=new AgentWorkspace(root)){var permissions=AgentPermissionRuntime.DefaultWorkspacePolicy();permissions.Add(new AgentPermissionRule{Action="read",Resource="private.txt",Effect=AgentPermissionEffect.Deny});w.ConfigureKernel(permissions,null);var scheduler=new AgentSubagentScheduler(new AgentSubagentManager(new ExecutionClaimStore(root)),4);using(var runner=new AgentSubagentRunner(w,scheduler,()=>new Model(),new ConnectionSettings())){var child=runner.Spawn("parent","private.txt");var result=(await runner.WaitAsync(new[]{child.Id},5,CancellationToken.None).ConfigureAwait(false)).Single();Check(!result.Result.Contains("PRIVATE EVIDENCE")&&result.Result.Contains("错误"),"read-only worker inherits parent resource denial");}}}
        static async Task Fifo(){var gates=new Gates();using(var w=new AgentWorkspace(root)){var scheduler=new AgentSubagentScheduler(new AgentSubagentManager(new ExecutionClaimStore(Path.Combine(root,"fifo-claims"))),4);using(var runner=new AgentSubagentRunner(w,scheduler,()=>new GateModel(gates),new ConnectionSettings())){for(int i=0;i<6;i++)runner.Spawn("fifo-parent",i.ToString());for(int i=0;i<500&&gates.Entered.Count<4;i++)await Task.Delay(10).ConfigureAwait(false);Check(gates.Entered.Count==4&&runner.List().Count(c=>c.Status=="queued")==2,"only four independent model calls run while two remain queued");gates.First.TrySetResult(true);for(int i=0;i<500&&gates.Entered.Count<5;i++)await Task.Delay(10).ConfigureAwait(false);Check(gates.Entered.Contains("4")&&!gates.Entered.Contains("5"),"completion promotes the earliest queued real worker");await runner.StopAsync().ConfigureAwait(false);Check(runner.List().Count(c=>c.Status=="completed")==1&&runner.List().Count(c=>c.Status=="cancelled")==5&&!scheduler.List("fifo-parent").Any(c=>c.Status=="running"),"parent stop cancels running and queued workers and releases scheduler slots");}}}
        static ApiClient Client(Wire wire){var api=new ApiClient(TimeSpan.FromSeconds(5));typeof(ApiClient).GetField("http",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).SetValue(api,new HttpClient(wire));return api;}
        static async Task Bytes(){var bytes=new byte[ChatAttachment.MaximumBytes];bytes[0]=137;bytes[1]=80;bytes[2]=78;bytes[3]=71;var image=ChatAttachment.CreateImage("fixture.png",bytes);var first=new ChatMessage("user","first");first.SetAttachments(new[]{image});var latest=new ChatMessage("user","latest");latest.SetAttachments(new[]{image});var messages=new[]{first,new ChatMessage("assistant","prior"),latest};var wire=new Wire();using(var api=Client(wire)){foreach(bool stream in new[]{false,true}){bool rejected=false;try{var s=new ConnectionSettings{BaseUrl="https://fixture.invalid",Model="fixture",ApiKey="fixture-only"};if(stream)await api.ChatStreamAsync(s,messages,null,CancellationToken.None);else await api.ChatAsync(s,messages,CancellationToken.None);}catch(ApiException){rejected=true;}Check(rejected&&wire.Body==null,"oversized total plain request stopped before HTTP, stream="+stream);}}}
        static async Task GitHub(){var approval=new Consent();var wire=new GitWire();using(var w=new AgentWorkspace(root)){var permissions=AgentPermissionRuntime.DefaultWorkspacePolicy();permissions.Add(new AgentPermissionRule{Action="github_write",Resource="**",Effect=AgentPermissionEffect.Ask});w.ConfigureKernel(permissions,null,approval,null,"github-fixture");w.ConfigureGitHub(new GitHubClient(new Uri("https://api.github.com"),wire,"fixture/project","fixture-key"));w.ConfigureDesktopSession();var pending=w.ExecuteAsync("github_create_issue","{\"title\":\"fixture\",\"body\":\"payload\"}","issue-1",CancellationToken.None);await approval.Arrived.Task.ConfigureAwait(false);Check(wire.Calls==0&&approval.Request.Resource.Contains("fixture/project")&&approval.Request.Arguments.Contains("payload"),"GitHub request waits for approval bound to exact repository and arguments");approval.Decision.SetResult(false);try{await pending.ConfigureAwait(false);}catch(UnauthorizedAccessException){}Check(wire.Calls==0,"denied GitHub write never reaches HTTP");approval.Decision=new TaskCompletionSource<bool>();var allowed=w.ExecuteAsync("github_create_issue","{\"title\":\"fixture\",\"body\":\"payload\"}","issue-2",CancellationToken.None);approval.Decision.SetResult(true);await allowed.ConfigureAwait(false);await w.ExecuteAsync("github_create_issue","{\"title\":\"fixture\",\"body\":\"payload\"}","issue-2",CancellationToken.None);Check(wire.Calls==1,"allowed duplicate GitHub call produces one HTTP write");}}
        static async Task DeepStore(){string directory=Path.Combine(root,new string('d',Math.Max(1,183-root.Length)));Directory.CreateDirectory(directory);var store=new AgentTaskStore(directory);var state=new AgentTaskState{Id="deep-fixture",PersonaId="work",Workspace=root,Goal="preserve"};await store.SaveAsync(state).ConfigureAwait(false);Check(String.IsNullOrEmpty(store.Warning)&&store.Load("work",root).Id==state.Id,"deep conversation checkpoint saves atomically without an overlong temporary filename");}
        static async Task Images(){var wire=new Wire();using(var api=Client(wire))using(var session=new ConversationSession(api,new Silent(),()=>null)){var cfg=new PetSettings{AgentEnabled=false,ReadReplies=false,Text=new ConnectionSettings{BaseUrl="https://fixture.invalid",Protocol="anthropic",Model="fixture",ApiKey="fixture-only",MetadataImageSupport=CapabilitySupport.Unsupported}};var image=ChatAttachment.CreateImage("small.png",new byte[]{137,80,78,71,0,0,0,0});bool rejected=false;try{await session.SendTextAsync("image",cfg,"pet",attachments:new[]{image}).ConfigureAwait(false);}catch(ApiException){rejected=true;}Check(rejected&&wire.Body==null&&!session.IsBusy,"explicit server image denial stops before request and leaves session idle");cfg.Text.ImageSupport=CapabilitySupport.Supported;await session.SendTextAsync("image",cfg,"pet",attachments:new[]{image}).ConfigureAwait(false);Check(wire.Body!=null&&session.History.Messages.Count==2,"user image override takes precedence in actual conversation path");}}
        static async Task UrlCredentials(){using(var manager=new McpConnectionManager()){bool refused=false;try{await manager.ConnectAsync(new McpServerConfiguration{Id="url-credentials",Enabled=true,Endpoint="https://user:fixture-secret@fixture.invalid/mcp"},new CancellationToken(true)).ConfigureAwait(false);}catch(ArgumentException){refused=true;}Check(refused,"MCP rejects plaintext credentials in URL before transport creation");}}
        static void PumpTask(Task task){var end=DateTime.UtcNow.AddSeconds(8);while(!task.IsCompleted&&DateTime.UtcNow<end){System.Windows.Threading.Dispatcher.CurrentDispatcher.Invoke(System.Windows.Threading.DispatcherPriority.ApplicationIdle,new Action(delegate{}));Thread.Sleep(5);}if(!task.IsCompleted)throw new Exception("background voice fixture timed out");task.GetAwaiter().GetResult();}
        static void VoiceScopes(){var cfg=new PetSettings{AgentEnabled=false,AgentWorkspace=root,ReadReplies=true,Volume=50,GreetingEnabled=false,AutoUpdate=false,SaveChatHistory=false};cfg.Text=new ConnectionSettings{BaseUrl="https://fixture.invalid",Model="fixture",ApiKey="fixture-only",StreamReplies=false};foreach(var key in cfg.Hotkeys.Keys.ToArray())cfg.Hotkeys[key]="";var api=new HeldConversation();var speech=new VoiceProbe();var pet=new PetWindow(null,cfg,new SettingsStore(Path.Combine(root,"voice-settings.json")),null);try{var manager=new ConversationWorkspaceManager(Path.Combine(root,"voice-scopes"),"pet",()=>api,()=>speech,()=>null,()=>cfg,()=>false);typeof(PetWindow).GetField("workspaces",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).SetValue(pet,manager);var workspace=manager.CreateWorkspace(new ProjectDefinition{Id="voice",Workspace=root},new ConversationDefinition{Id="voice-chat",Mode="chat"});var first=workspace.Session.SendTextAsync("wait",workspace.EffectiveSettings(),"pet");pet.SetReplySpeech(false);api.Reply.SetResult("kept reply");PumpTask(first);Check(speech.Calls==0&&workspace.Session.History.Messages.Last().Content=="kept reply","mute during thinking suppresses later speech in an effective-settings snapshot");pet.SetReplySpeech(true);api.Reply=new TaskCompletionSource<string>(TaskCreationOptions.RunContinuationsAsynchronously);var second=workspace.Session.SendTextAsync("volume",workspace.EffectiveSettings(),"pet");cfg.Volume=23;pet.UpdateVoiceVolume(23);api.Reply.SetResult("second kept reply");PumpTask(second);Check(speech.Calls==1&&speech.Volume==23,"changed global volume reaches the pending background reply");}finally{pet.Close();}}
        static async Task WorkerUsage(){using(var w=new AgentWorkspace(root)){w.ConfigureKernel(AgentPermissionRuntime.DefaultWorkspacePolicy(),null,null,new ExecutionClaimStore(Path.Combine(root,"claims")),"usage-parent");w.BeginTask(new AgentTaskState{Id="usage-parent",Workspace=root,Goal="read"});w.ConfigureWorkers(()=>{var api=new ApiClient();typeof(ApiClient).GetField("http",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).SetValue(api,new HttpClient(new LoopWire()));return api;},new ConnectionSettings{BaseUrl="https://fixture.invalid",Model="fixture",ApiKey="fixture-only",Protocol="openai"});w.ConfigureDesktopSession();string spawned=await w.ExecuteAsync("spawn_subagent","{\"profile\":\"explore\",\"input\":\"read private.txt\"}","usage-spawn",CancellationToken.None);var json=new JavaScriptSerializer();string id=(string)((Dictionary<string,object>)json.DeserializeObject(spawned))["Id"];await w.ExecuteAsync("wait_subagents",json.Serialize(new{ids=new[]{id},timeout_seconds=5}),"usage-wait",CancellationToken.None);var child=w.TaskState.Children.Single();Check(child.Status=="completed"&&child.ToolCalls==1&&child.ModelRequests==2&&child.EstimatedTotalTokens==300&&child.EstimatedTokens>0,"worker accounts for both actual native requests and the file-tool round");Check(w.TaskState.ChildEstimatedTotalTokens==300,"parent total includes real worker usage separately from current context");}}
        static async Task Output(){foreach(int capacity in new[]{0,8192,32768}){var wire=new Wire();using(var client=Client(wire)){var s=new ConnectionSettings{BaseUrl="https://fixture.invalid",Protocol="anthropic",ApiKey="fixture-only",Model="fixture",ContextWindowTokens=capacity};await client.ChatAsync(s,new[]{new ChatMessage("user","hello")},CancellationToken.None);var body=new JavaScriptSerializer().DeserializeObject(wire.Body) as Dictionary<string,object>;Check(Convert.ToInt32(body["max_tokens"])<=AgentContextPolicy.Resolve(ModelContextCapacity.Budget(s,8192)).OutputReserve,"plain Anthropic output respects reserved tokens "+capacity);using(var w=new AgentWorkspace(root){ContextTokenLimit=8192}){await client.ChatAgentAsync(s,new[]{new ChatMessage("user","hello")},w,null,null,null,false,CancellationToken.None);body=new JavaScriptSerializer().DeserializeObject(wire.Body) as Dictionary<string,object>;Check(Convert.ToInt32(body["max_tokens"])<=AgentContextPolicy.Resolve(w.ContextTokenLimit).OutputReserve,"native Anthropic output respects task reserve "+capacity);}}}}
    }
